const fs=require('fs'),path=require('path'),assert=require('assert/strict'),crypto=require('crypto');
(async()=>{const url='http://127.0.0.1:8765/api/project?id=scene-inn-20261119',r=await fetch(url);assert(r.ok);const raw=await r.text(),p=JSON.parse(raw),original=JSON.parse(fs.readFileSync('output/inn-otterisk96-1795242177186/before.json')),out=path.resolve('output/inn-sign-restore-'+Date.now());fs.mkdirSync(out,{recursive:true});fs.writeFileSync(path.join(out,'project-before.json'),raw);const dest='C:/Users/Administrator/Desktop/最后/游戏资产/游戏内部/旅馆/旅馆招牌.png',source='output/inn-export-1795242384860/originals/旅馆招牌.png';fs.copyFileSync(dest,path.join(out,'sign-before.png'));const si=p.spriteSheets.findIndex(s=>s.name==='旅馆招牌'),oi=original.spriteSheets.findIndex(s=>s.name==='旅馆招牌');assert(si>=0&&oi>=0);p.spriteSheets[si].imageDataURL=original.spriteSheets[oi].imageDataURL;const oldLayers=original.layers.filter(l=>l.sheetIndex===oi),layers=p.layers.filter(l=>l.sheetIndex===si);assert.equal(layers.length,oldLayers.length);layers.forEach((l,i)=>{assert.equal(l.name,oldLayers[i].name);l.frameData=structuredClone(oldLayers[i].frameData);});const save=await fetch(url,{method:'PUT',headers:{'Content-Type':'application/json','X-Pixel-Editor':'1','If-Match':r.headers.get('etag')},body:JSON.stringify(p)});assert(save.ok,await save.text());assert.deepEqual(await(await fetch(url)).json(),p);fs.copyFileSync(source,dest);assert.deepEqual(fs.readFileSync(source),fs.readFileSync(dest));const hash=b=>crypto.createHash('sha256').update(b).digest('hex');const report={restoredFile:dest,originalSHA256:hash(fs.readFileSync(source)),restoredSHA256:hash(fs.readFileSync(dest)),projectSignRestored:true,projectReadbackVerified:true};fs.writeFileSync(path.join(out,'verification.json'),JSON.stringify(report,null,2));assert.deepEqual(JSON.parse(fs.readFileSync(path.join(out,'verification.json'))),report);console.log(JSON.stringify(report,null,2));})().catch(e=>{console.error(e);process.exitCode=1});
